import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { format } from 'date-fns';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import LoadingSpinner from '../components/LoadingSpinner';
import toast from 'react-hot-toast';

const EventDetails = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { user, isAuthenticated } = useAuth();
    const [event, setEvent] = useState(null);
    const [loading, setLoading] = useState(true);
    const [isRegistered, setIsRegistered] = useState(false);
    const [checkingRegistration, setCheckingRegistration] = useState(true);

    useEffect(() => {
        fetchEvent();
    }, [id]);

    useEffect(() => {
        if (isAuthenticated && event) {
            checkRegistration();
        }
    }, [isAuthenticated, event]);

    const fetchEvent = async () => {
        try {
            const response = await api.get(`/events/${id}`);
            setEvent(response.data);
        } catch (error) {
            console.error('Error fetching event:', error);
            toast.error('Event not found');
            navigate('/events');
        } finally {
            setLoading(false);
        }
    };

    const checkRegistration = async () => {
        try {
            const response = await api.get('/dashboard/registrations');
            const registered = response.data.upcoming.some(
                reg => reg.event._id === id || reg.event === id
            );
            setIsRegistered(registered);
        } catch (error) {
            console.error('Error checking registration:', error);
        } finally {
            setCheckingRegistration(false);
        }
    };

    const handleRegister = async () => {
        if (!isAuthenticated) {
            navigate('/login');
            return;
        }

        try {
            await api.post(`/events/${id}/register`);
            setIsRegistered(true);
            setEvent(prev => ({
                ...prev,
                availableSeats: prev.availableSeats - 1
            }));
            toast.success('Successfully registered for event!');
        } catch (error) {
            const message = error.response?.data?.message || 'Registration failed';
            toast.error(message);
        }
    };

    const handleCancel = async () => {
        try {
            await api.delete(`/events/${id}/register`);
            setIsRegistered(false);
            setEvent(prev => ({
                ...prev,
                availableSeats: prev.availableSeats + 1
            }));
            toast.success('Registration cancelled');
        } catch (error) {
            const message = error.response?.data?.message || 'Cancellation failed';
            toast.error(message);
        }
    };

    if (loading) return <LoadingSpinner />;

    const eventDate = new Date(event.date);
    const isUpcoming = eventDate > new Date();
    const seatsAvailable = event.availableSeats > 0;

    return (
        <div className="min-h-screen bg-gray-50 py-8">
            <div className="container mx-auto px-4">
                <div className="bg-white rounded-lg shadow-lg overflow-hidden">
                    <div className="h-64 bg-gradient-to-r from-purple-600 to-blue-600"></div>
                    
                    <div className="p-8">
                        <div className="flex justify-between items-start mb-6">
                            <h1 className="text-3xl font-bold text-gray-800">
                                {event.name}
                            </h1>
                            <span className={`px-4 py-2 rounded-full text-sm font-semibold ${
                                isUpcoming ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                            }`}>
                                {isUpcoming ? 'Upcoming Event' : 'Past Event'}
                            </span>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                            <div className="lg:col-span-2 space-y-6">
                                <div>
                                    <h2 className="text-xl font-semibold mb-3 text-gray-800">
                                        About This Event
                                    </h2>
                                    <p className="text-gray-600 leading-relaxed">
                                        {event.description}
                                    </p>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div className="bg-gray-50 p-4 rounded-lg">
                                        <div className="text-sm text-gray-500">Organizer</div>
                                        <div className="font-semibold text-gray-800">{event.organizer}</div>
                                    </div>
                                    <div className="bg-gray-50 p-4 rounded-lg">
                                        <div className="text-sm text-gray-500">Category</div>
                                        <div className="font-semibold text-gray-800">{event.category}</div>
                                    </div>
                                    <div className="bg-gray-50 p-4 rounded-lg">
                                        <div className="text-sm text-gray-500">Location</div>
                                        <div className="font-semibold text-gray-800">{event.location}</div>
                                    </div>
                                    <div className="bg-gray-50 p-4 rounded-lg">
                                        <div className="text-sm text-gray-500">Date & Time</div>
                                        <div className="font-semibold text-gray-800">
                                            {format(eventDate, 'PPP')} at {format(eventDate, 'p')}
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="lg:col-span-1">
                                <div className="bg-gray-50 p-6 rounded-lg">
                                    <h3 className="text-lg font-semibold mb-4 text-gray-800">
                                        Registration
                                    </h3>
                                    
                                    <div className="mb-4">
                                        <div className="text-3xl font-bold text-purple-600">
                                            {event.availableSeats}
                                        </div>
                                        <div className="text-sm text-gray-500">
                                            Seats Available out of {event.capacity}
                                        </div>
                                    </div>

                                    {isUpcoming ? (
                                        seatsAvailable ? (
                                            isRegistered ? (
                                                <div className="space-y-3">
                                                    <div className="bg-green-100 text-green-800 p-3 rounded-lg text-center font-semibold">
                                                        You're registered for this event!
                                                    </div>
                                                    <button
                                                        onClick={handleCancel}
                                                        className="w-full bg-red-600 text-white py-3 rounded-lg hover:bg-red-700 transition"
                                                    >
                                                        Cancel Registration
                                                    </button>
                                                </div>
                                            ) : (
                                                <button
                                                    onClick={handleRegister}
                                                    disabled={checkingRegistration}
                                                    className="w-full bg-gradient-to-r from-purple-600 to-blue-600 text-white py-3 rounded-lg hover:from-purple-700 hover:to-blue-700 transition disabled:opacity-50"
                                                >
                                                    {checkingRegistration ? 'Checking...' : 'Register Now'}
                                                </button>
                                            )
                                        ) : (
                                            <div className="bg-red-100 text-red-800 p-3 rounded-lg text-center font-semibold">
                                                Sold Out
                                            </div>
                                        )
                                    ) : (
                                        <div className="bg-gray-200 text-gray-600 p-3 rounded-lg text-center font-semibold">
                                            Event has ended
                                        </div>
                                    )}

                                    {!isAuthenticated && (
                                        <p className="text-sm text-gray-500 mt-4 text-center">
                                            Please login to register for this event
                                        </p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default EventDetails;
